INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052R3ZN160W7VTBA69E9GNN', '01M052PRC8AKV31ND1YD9TYMQ8', 'Any path a test resolves runs through the user''s home directory.', 'must_not', 9, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052R9CT9QZXPHQP1FQM0M4X', '01M052PT0XX69QRRH81SA6WS0B', 'Given a root holding the running version and a higher-numbered sibling, the check reports a skew naming the higher version.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052RAVS4JZP8HR1MDNNDGWM', '01M052PT0XX69QRRH81SA6WS0B', 'Given a root whose siblings are all lower than or equal to the running version, the check reports no skew.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052RCEGFJVZQ959EX996TRN', '01M052PT0XX69QRRH81SA6WS0B', 'Given a root whose name does not parse as a version, the check reports could-not-check.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052RE7EQDQ8DS32YBX60BB5', '01M052PT0XX69QRRH81SA6WS0B', 'Given a root with no sibling directories at all, the check reports could-not-check rather than no skew.', 'must', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052RFV6MW9X2JRD8PB74S8R', '01M052PT0XX69QRRH81SA6WS0B', 'The three states — skew found, no skew, could not check — are distinguishable without parsing message text.', 'must', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052RHFYNA4Z7EBTFTSW9X2E', '01M052PT0XX69QRRH81SA6WS0B', '`dependencies` and `devDependencies` are both empty.', 'must', 5, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052RK0W7EGK2XK69S0EPCTC', '01M052PT0XX69QRRH81SA6WS0B', 'The check reports a skew for a sibling lower than the running version. A reversed comparison satisfies the first criterion on any machine with more than one version installed, so the first criterion alone does not pin the direction.', 'must_not', 6, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052RMVD075AE45MWYNJAWXX', '01M052PT0XX69QRRH81SA6WS0B', 'The check throws for an unreadable or unparseable root.', 'must_not', 7, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052RPGFSXGRVMBDRV4T6WNK', '01M052PT0XX69QRRH81SA6WS0B', 'A check that could not run renders as no skew.', 'must_not', 8, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052RRNYYCRKN50ZF86RTYHG', '01M052PVJ78F729JVQ3374SKS7', 'Two consecutive reports against a root that gained a higher sibling between them return different verdicts.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052RTV9GJCTR4JY5NNY657Z', '01M052PVJ78F729JVQ3374SKS7', 'With the check deliberately memoised, the two-consecutive-reports criterion fails, and the failure has been observed and read rather than assumed.', 'control', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052RZT6HV2HP1RHYW0X639A', '01M052PX5CZY0C594F5DZ7DMEQ', 'The skew field is present in the response when no skew was found.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052S1C4034VWQYWQS2ZM7GJ', '01M052PX5CZY0C594F5DZ7DMEQ', 'A reported skew contains the running version, the newer version found, and a remedy naming a session restart.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052S31SKSFTMP5QWD5VGGN6', '01M052PX5CZY0C594F5DZ7DMEQ', 'A directory read that throws produces could-not-check and a successful tool response.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052S4N4YF8TAWXZ4NMB8AMF', '01M052PX5CZY0C594F5DZ7DMEQ', 'The skew sentence is composed in more than one place.', 'must_not', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052S6D4P10XDG6R2TT4E29G', '01M052PX5CZY0C594F5DZ7DMEQ', 'An error from the check propagates out of the tool handler.', 'must_not', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052S8FPFR6581KF0941DEG2', '01M052PX5CZY0C594F5DZ7DMEQ', 'A version skew changes `ok`. The report''s `ok` states that the database is internally consistent, and under a skew it still is — the rows are sound and the reader is stale.', 'must_not', 5, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052SA77ZAZBV0A1VDPH7KJG', '01M052PX5CZY0C594F5DZ7DMEQ', 'A version skew appears in `entries`. That list is derived from the register and held to it by a parity test; a skew there is either a fabricated register entry or a broken derivation.', 'must_not', 6, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052SCJKDPTM2XZH0V72YTEG', '01M052PX5CZY0C594F5DZ7DMEQ', 'With the error handling removed, the criterion that a throwing read produces could-not-check fails, and that failure has been observed and read rather than assumed.', 'control', 7, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052SE84XB26KDG3CXVBM1P4', '01M052PYQDDQ7DH1QBGNZADESJ', 'The maintenance record documents the assumed plugin cache layout and what breaks if the host changes it.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052SGPKZGDG7HQXQZ0HK26Q', '01M052PYQDDQ7DH1QBGNZADESJ', 'Any file under the skills directory names the maintenance record''s path.', 'must_not', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052Z4RNRJAETPKB06KZE5AP', '01M052YZWZ5SEB1HYP9VY0TR72', 'A `check_integrity` call against a constructed root holding a higher sibling returns a skew field naming both versions, with `ok` still true.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M052Z6DN5EFBHM69HSXG3SZD', '01M052YZWZ5SEB1HYP9VY0TR72', 'A `check_integrity` call against a root that is not a version directory returns could-not-check, with `ok` still true.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053HCW0ZZ1RDDGZ60WFFJYX', '01M053DWR0V5SD8P9SREMJZP1E', 'After `migrate()` on an empty database, the stamp table exists.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053HEK7HE0S91PJVEBACT2M', '01M053DWR0V5SD8P9SREMJZP1E', '`migrate()` run twice against the same database applies the new migration once and leaves the table''s contents unchanged.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053HG6EPK2WCRD2E38R5VTS', '01M053DWR0V5SD8P9SREMJZP1E', 'A database at the previous schema version gains the stamp table when migrated, and no other table''s contents change.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053HHWJPCWAMK34RRYKCZYJ', '01M053DWR0V5SD8P9SREMJZP1E', 'A server whose target version is below the migrated database''s version returns `ahead: true` and serves the read-only tool set. This is the one-time lockout of older servers that AD2 accepted deliberately, asserted here rather than discovered in the field.', 'must', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053HKBPPRRRQJRPWC8WDHDR', '01M053DWR0V5SD8P9SREMJZP1E', 'The table admits a second row.', 'must_not', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053HN3BRN2Z9PEQCGN4W10A', '01M053DWR0V5SD8P9SREMJZP1E', 'The migration inserts a row as part of applying itself. Migration SQL is static and cannot know the running version, so a row written there would carry a placeholder — and FR2 already says the value arrives on the next start.', 'must_not', 5, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053HPW1ER9QQDKHNQDH2S59', '01M053DYJ1RV66CC6XZ9ZF89E1', 'The resolver returns the version stated in the plugin''s own manifest.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053HRAPM39GMQ6BXYXGCSEH', '01M053DYJ1RV66CC6XZ9ZF89E1', 'The resolver returns a version when the plugin is loaded from a working tree, where no version directory exists.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053HSV55179W454ZJQ9EPSW', '01M053DYJ1RV66CC6XZ9ZF89E1', 'The resolver derives the version from the containing directory''s name. That is the neighbour check''s mechanism, and it yields nothing in a working tree — which is the whole reason this resolver is separate from it.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053HVBHVCRPXGZZXXY009S6', '01M053DYJ1RV66CC6XZ9ZF89E1', 'The resolver takes any value from `process.env`.', 'must_not', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053J07S15FFWTYAW6H2DBKE', '01M053E06Z2GM9R7STNT70P8VM', 'A database started by a server at version X carries X as its recorded plugin version.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053J1VX1E44W7NX322MPWR5', '01M053E06Z2GM9R7STNT70P8VM', 'A database migrated from before the stamp existed acquires the running version on the next start.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053J4Q38WKT494XXC3NWXAC', '01M053E06Z2GM9R7STNT70P8VM', 'A server at the recorded version leaves the row untouched.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053J6A95CDX39BK7B90B3NZ', '01M053E06Z2GM9R7STNT70P8VM', 'A server below the recorded version leaves the row untouched — the stamp never moves backwards.', 'must', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053J7XCXND5BQEKA1MV2KNJ', '01M053E06Z2GM9R7STNT70P8VM', 'A server above the recorded version replaces it.', 'must', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053J9E34XJD6HT3TDY30XTT', '01M053E06Z2GM9R7STNT70P8VM', 'Two consecutive starts at the same version, with no planning data changed, produce byte-identical dumps.', 'must', 5, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053JAYJ6GK645AX7A1C3Q8M', '01M053E06Z2GM9R7STNT70P8VM', 'A start that raises the recorded version does change the dump. Without this positive half, a comparison that is broken — reading the wrong file, comparing nothing to nothing — passes the byte-identical criterion perfectly.', 'must', 6, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053JCHSC0W08S8JMYKMPR7J', '01M053E06Z2GM9R7STNT70P8VM', 'A read-only launch writes the stamp. The read-only path exists so a board can observe every registered project without touching any of them; a stamp written on observation would diverge every one of those projects from its committed dump, and the owner would find the guard refusing a commit in a repository they had not opened.', 'must_not', 7, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053JF4Q231SKY3272VMSRK3', '01M053E06Z2GM9R7STNT70P8VM', 'The row carries a value that differs between two runs of the same version. This is NFR3 stated where it can be checked: a timestamp column would satisfy every other criterion here and still diverge the dump on every start, which is the exact failure the requirement exists to prevent — while looking like good practice.', 'must_not', 8, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053JGSWTC56HXH67R1VYNF4', '01M053E06Z2GM9R7STNT70P8VM', 'With the write made unconditional, the criterion that a server at the recorded version leaves the row untouched fails, and that failure has been observed and read rather than assumed.', 'control', 9, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053MQ6SQHARJSV0C73RA6HK', '01M053E1Q8TDNDN5B78V98WD47', 'A database stamped above the running version produces a skew naming both versions.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053MRRYJXWJYYHMPR75YXMZ', '01M053E1Q8TDNDN5B78V98WD47', 'A database stamped at or below the running version produces no skew.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053MTFVYVRNY0XBDQ2P0S8S', '01M053E1Q8TDNDN5B78V98WD47', 'A database whose stamp table is absent produces could-not-check rather than no skew. This is the read-only launch against a project the release has never opened: the table will not be there, and no-skew would be a lie told confidently.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053MWBCVQPPGC75B9SP714Q', '01M053E1Q8TDNDN5B78V98WD47', 'A stamp comparison that throws yields could-not-check and the call it was made from succeeds.', 'must', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053MXWVEDK9RDKHVSD56H3X', '01M053E1Q8TDNDN5B78V98WD47', 'An absent or unreadable stamp renders as checked-and-found-no-skew.', 'must_not', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053MZGCYSMG9KTYB84CJ708', '01M053E3BFMFVWFRFCEP2SFYPY', 'A database stamped above the running version writes a line to stderr when opened.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053N15HS8C67EDSM263FYWH', '01M053E3BFMFVWFRFCEP2SFYPY', 'The stamp skew reaches `check_integrity` through the same top-level field the neighbour skew uses.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053N2V6VZ1C8186MZN4QNVG', '01M053E3BFMFVWFRFCEP2SFYPY', 'The stamp skew''s sentence names the version running, the version recorded, and the remedy.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053N4DHBCSY3Q2MSEVGN1BZ', '01M053E3BFMFVWFRFCEP2SFYPY', 'A clean open writes anything to stderr. This continues the rule the project already holds — a clean session is silent there — which is what makes any line that does appear worth reading.', 'must_not', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053N605S3ZV8SQ30RNMVJJ6', '01M053E3BFMFVWFRFCEP2SFYPY', 'The stamp skew adds a second top-level field distinct from the neighbour''s. AD1 gave the skew one field beside `entries` and `orphans`; two fields would make a caller check both to learn whether anything is stale.', 'must_not', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053N7SGB97EMC98VFRM71P7', '01M053E4Z5EW3VZ5FBQ4FNXWB4', 'A read-only launch''s integrity response carries the same skew field, in the same three states, as an ordinary one.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053N9JMBC9SQ86B8H39NVGE', '01M053E4Z5EW3VZ5FBQ4FNXWB4', 'A read-only launch reports a neighbour skew as well as a stamp skew. It never reaches `start()`, so both detectors have to be reachable from the read-only open for either to arrive.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053NBGJJ0V2N1D4CM558B6V', '01M053E4Z5EW3VZ5FBQ4FNXWB4', 'A read-only launch writes to the database or to the filesystem while reporting a skew.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053TPW5K7BT8W0GZKB99Q0Y', '01M053T5F2BHGEB0A3RBPX8Z8T', 'A database stamped by a newer server and then opened by an older one produces a skew on `check_integrity` naming both versions, and a line on stderr, in a single run exercising the table, the write, the comparison and the report.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M053TS144GH9X2VNPRHD01Q7', '01M053T5F2BHGEB0A3RBPX8Z8T', 'Two consecutive full starts at the same version, with the neighbour check running as well, leave the committed dump byte-identical. This is not story 3''s comparison repeated: it adds the other epic''s detector to the run, which is where the two meet.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05NTME0MRWDJKSM4DD65YQK', '01M05NTFP3SP5G00T656J93QFX', 'The fixture builds, and holds at least one epic or story in each state the model defines — including `complete`, `superseded` and `withdrawn` — together with a document long enough to time a render against.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05NTNNSX25CF3YWCZ58NB2E', '01M05NTFP3SP5G00T656J93QFX', 'The fixture build writes anywhere outside the directory the test owns.', 'must_not', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05NTQ1XYYJF2Q29Y5H819C1', '01M05NTGKBR1C512G581KVZH52', 'pytest and pytest-asyncio are present at or above the stated minimums, and the suite runs from `dpm/tools/board`.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05NTRQ3K4YGTV51SAYFRJYR', '01M05NTGKBR1C512G581KVZH52', 'The dependency list in `pyproject.toml` and the PEP 723 inline block in `board.py` name the same packages.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05NTS6XA6A5HSPGW14CJYCK', '01M05NTGKBR1C512G581KVZH52', 'The markdown renderer imports, and neither dependency list has gained an entry for it.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05NTTG64NGCBJWCF0Q4G3YZ', '01M05NTGKBR1C512G581KVZH52', 'A socket opened during the suite raises and is recorded, so the run is known to have needed no network rather than assumed to have needed none.', 'must', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05NTVWFT97H2KN1MFYBHK5H', '01M05NTGKBR1C512G581KVZH52', '`board.py` imports nothing outside the standard library and the packages its own inline block declares.', 'must', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05NTWFYPZW3BG29M967A5DY', '01M05NTGKBR1C512G581KVZH52', 'The host running the board has Python 3.11 or later, and `uv run` provisions the board from its inline block there.', 'must', 5, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05P6GJQNEJ96Q0Q88MBNC98', '01M05P6A9HYV9QSZJNAP2NB3CY', 'Driving a running board: `r` re-reads every registered project, `R` empties the cache, `a` opens the register picker, and `x` unregisters the highlighted project.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05P6HY7K4WSK6SX299EED7H', '01M05P6A9HYV9QSZJNAP2NB3CY', 'Refresh and unregister are reachable by key, not only through the command palette as they are today.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05P6KA007DFB84N2463DKXR', '01M05P6A9HYV9QSZJNAP2NB3CY', 'No key the CPM board binds does something different on the DPM board.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05P6MP4D0BTKCGC1RAW18Y2', '01M05P6AZSWD3EZ6JY58YZ1SDG', 'A board opened over a project holding complete, superseded, withdrawn and live rows shows only the live ones; `z` reveals all four groups; `z` again returns to the first state.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05P6P3DP6TZ16WKYP6DPHP6', '01M05P6AZSWD3EZ6JY58YZ1SDG', 'Each press says which way it went, so a board that was already showing everything is distinguishable from one that has just been told to.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05P6QE53A3NEXH0EFAPRGDW', '01M05P6AZSWD3EZ6JY58YZ1SDG', 'No row in a live state — ready, in progress, blocked or pending — is removed by the filter, with one case per live state rather than one case for the set.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05P6SH405DXTD0CR73QECPD', '01M05P6AZSWD3EZ6JY58YZ1SDG', 'With the filter widened to hide a live state, the case above fails and names the state it lost — so a filter that removed nothing at all could not pass it.', 'control', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05P6TWQ1SWTGYGBQ90PGEQ0', '01M05P6CEFYY4RZ2KYA6TG1ESC', 'Driving a running board: `ctrl+r` re-reads every project ignoring the cache, `ctrl+f` opens search, `ctrl+g` opens coverage gaps.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05P6W8R10VSEKPK1FHREG05', '01M05P6CEFYY4RZ2KYA6TG1ESC', 'No capability the DPM board has and the CPM board lacks is bound to a key that appears in the CPM board''s map, read from that board''s source by the same reader story 1 uses.', 'must_not', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05P6XMXNMW9RDD3A6NSZZ0T', '01M05P6D3M5WR5CRXGD2K1M9G6', 'The footer shows every bound key, using the CPM board''s wording wherever the action is the same one.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05P6YHN6SZS3BVSV0JWFGTH', '01M05P6D3M5WR5CRXGD2K1M9G6', 'No footer label or palette entry describes a key that is not bound, and no bound key is missing from the footer — both directions, because either alone is satisfied by a board that documents nothing.', 'must_not', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05PHTKQ9PQC4JJ7J91WKF2K', '01M05PHNRSGHHF8844AHMJ2E7M', 'Changing a DPM binding so that a key the CPM board binds does something else makes the parity check fail, and the failure names the key.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05PHW1PCJ79W77PN8D9AY8P', '01M05PHNRSGHHF8844AHMJ2E7M', 'An unreadable CPM tree makes the check fail rather than skip, and the failure names what it could not read.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05PHXBVDTNHCT2R9M5AQR38', '01M05PHNRSGHHF8844AHMJ2E7M', 'The CPM board''s source is readable at `cpm/tools/board/` relative to the marketplace checkout root, from the directory the suite runs in.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05PHYTVWQ4TEQHVJAH1VRK9', '01M05PHNRSGHHF8844AHMJ2E7M', 'The board starts, paints its columns and answers its keys with no CPM tree anywhere on its path.', 'must', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05PJ04C7NC98SQ9B23W3F19', '01M05PHNRSGHHF8844AHMJ2E7M', 'The check does not assert equality between the two key maps: binding a new DPM-only capability to a key the CPM board does not use leaves it passing.', 'must_not', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05PJ1K053SHQH0HMM96DXYC', '01M05PHNRSGHHF8844AHMJ2E7M', 'The check reads the CPM board from the installed plugin cache. The cache is overwritten on update, so a check reading it asserts against a copy nobody edits and stays green while the repository source diverges.', 'must_not', 5, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05PJ2Y927AH9W714D0MR3FA', '01M05PHPG35ET1G8J5B9AYNHVT', 'Bindings, footer and command palette each have a recorded outcome: a difference closed, a difference recorded as deliberate, or a statement that the surface agrees.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05PJ4EQQG7NG971CPK6VHZD', '01M05PHPG35ET1G8J5B9AYNHVT', 'None of bindings, footer or command palette is left with no outcome recorded. A surface nobody compared reads exactly like one that was compared and agreed.', 'must_not', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05QKA637JGDE7NZNP4TMHKA', '01M05QK3RW4P1MV94JBZ2MZ5E6', 'The strip rendered for the highlighted row carries that row''s own colour blended toward the background — a red row and a green row highlight differently, and neither highlights in a fixed accent colour.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05QKBM8KWJTV6FXEFK1WDWQ', '01M05QK3RW4P1MV94JBZ2MZ5E6', 'Textual''s own highlight style appears on no rendered row, whether or not the list has focus.', 'must_not', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05QKDNKTTPPAQNE1HMBGTWT', '01M05QK3RW4P1MV94JBZ2MZ5E6', 'With the CSS override removed, the criterion above fails — so a board rendering no highlight at all could not satisfy it by having nothing to find.', 'control', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05QKF08S97Z6PG34299XS66', '01M05QK55CWG63177HY888NMAG', 'A projects row rendered at column width 24 and again at 48 puts the pill''s last character in the row''s last column both times.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05QKGCJQPMHB02CAPW5RZY2', '01M05QK55CWG63177HY888NMAG', 'The pill and the badge each render in their own colour rather than the row''s status colour, on a row whose status colour differs from both.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05QKHVR0A05MZYD5SYWF2VT', '01M05QK55CWG63177HY888NMAG', 'Neither pill nor badge is truncated on a row too narrow to hold everything: the project name is what gives.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05QKK4MSC0PKP6ZTQB3JFHS', '01M05QK5SX4FZGWHZ9GPZTVXWH', 'With the console limited to 256 colours, the highlighted row is still distinguishable from an unhighlighted one, and the pill from the row''s own colour.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05QKMGSAECRH75H13EDKT4Q', '01M05QK5SX4FZGWHZ9GPZTVXWH', 'The board renders against a console reporting 256 colours without error, and the render is not silently a monochrome one.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05QSGQJRHXPEBPVGWMTEVTC', '01M05QS8M3SRW6203DQXVBN1G4', '`document_preview` returns the document''s title as a markdown heading and each section''s heading as a heading beneath it.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05QSJ2Q0KDQQZ38TBVDM1QG', '01M05QS8M3SRW6203DQXVBN1G4', '`story_preview` returns the story''s criteria and tasks as markdown lists, with a task''s description subordinate to the task rather than beside it.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05QSKE9QHKW4W3859S84434', '01M05QS8M3SRW6203DQXVBN1G4', 'No plain-text scaffolding label survives in either builder''s output — a bare `Acceptance criteria:` line renders as prose and is the shape this requirement exists to remove.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05QSMW3AM5HM46PP2RX6JZR', '01M05QS9B3SYZE15YZR6T733RD', 'Source containing a heading, emphasis, a list and a table renders each as a styled construct rather than as its source characters.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05QSP86E4YWR0ASQV10WK62', '01M05QS9B3SYZE15YZR6T733RD', 'The same source rendered at two panel widths breaks its lines differently, so the render is using the panel''s width rather than a default.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05QSQJY4PWA39TXAD1SHNHB', '01M05QS9B3SYZE15YZR6T733RD', 'Resizing the panel re-renders its contents at the new width.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05QSRZ1NYQ5ZCWN4V1DHD2P', '01M05QS9B3SYZE15YZR6T733RD', 'The panel''s renderable is built from styled text rather than being a live markdown widget, which is what leaves the rendered preview selectable.', 'must', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05QSTAZPM0TNPBT0C11168X', '01M05QS9B3SYZE15YZR6T733RD', 'No markdown marker survives into the rendered output for a construct that was rendered — no `##` before a heading, no `- ` before a list item, no `**` around emphasis.', 'must_not', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05QSVQ6J2FHMA9G3KTJSTW1', '01M05QSAPA8MP912VBFV9M9GEX', 'A render for a row the cursor has since left is discarded rather than painted, so moving quickly through a list leaves the panel showing the row the cursor is on.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05QSX5QT38SSW5VB3P4HR7D', '01M05QSAPA8MP912VBFV9M9GEX', 'Rendering the largest document in the fixture at 80 columns completes within 50 ms.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05QSYFQPZJFDY2BJERR95EY', '01M05QSC2DD8CBEAKHR53440NS', 'A preview whose source is malformed, pathologically nested, or a single very long line renders something and leaves the board running.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05QSZWA9KT74GW135HPZD82', '01M05QSC2DD8CBEAKHR53440NS', 'With the guard removed, a render that raises takes the board down — so the criterion above cannot pass against a panel that was never protecting itself. No markdown source has been found that makes the renderer raise, so the control drives the failure through the renderer rather than through the input.', 'control', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05QT17V47D07M1J375K4V8Y', '01M05QSCJCT9JBH0BQSVQJYCVS', 'Column layout, row composition, CSS and preview behaviour each have a recorded outcome: a difference closed, a difference recorded as deliberate, or a statement that the surface agrees.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05QT2EACFAJA00984CASMEF', '01M05QSCJCT9JBH0BQSVQJYCVS', 'None of column layout, row composition, CSS or preview behaviour is left with no outcome recorded. A surface nobody compared reads exactly like one that was compared and agreed.', 'must_not', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M05R99VD3D4QC4TX5HCMWJMV', '01M05QK3RW4P1MV94JBZ2MZ5E6', 'Moving the cursor onto a row on a running board paints that row''s strip in its own colour.', 'must', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M061C06R5MCXD588KC82YVNX', '01M05QS9B3SYZE15YZR6T733RD', 'A preview the raster produced reaches a terminal reporting 256 colours as 8-bit colour and no 24-bit codes, so no colour system named where the terminal cannot be seen decides whether a preview is legible.', 'must', 5, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z7SGNCQ5R0QE8RG7KXQEZX', '01M0Z7S9PASBDQ22FEPYJYR9FX', 'The fixture contains a `coverage_matrix` under an epic under a spec, so a derivation taking the document''s own `sequence` rather than its epic''s produces a different answer and the comparison fails. Without that row the two derivations agree and the criterion above verifies nothing.', 'control', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z7SJQFBDKCR553G3XFNM1J', '01M0Z7S9PASBDQ22FEPYJYR9FX', 'The fixture holds a document with no root-numbered ancestor, `numbering = ''none''` — one of each — so the unnameable cases have rows to be observed against.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z7SMT88GTF6VF6AGSWCMJ0', '01M0Z7SB2BKX98TG7HEH9T8ZGE', 'Every tool in the built registry whose name begins `list_` or `read_` and whose returned rows are `document` rows carries a `reference` field on each row. The set of such tools is enumerated from the registry itself, never from a written list of tool names.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z7SP5T1HJ74RR0WWYNQED8', '01M0Z7SB2BKX98TG7HEH9T8ZGE', 'The check must not invoke `defineTool` directly. It calls the registered handlers against a real database, so a wrapper that works in isolation but was never wired to any tool fails.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z7SQHWVQTT3D4F1G1BZXGR', '01M0Z7SB2BKX98TG7HEH9T8ZGE', 'For every document in a fixture corpus, the `reference` a tool returns equals the identifier embedded in that document''s `pathOf` filename.', 'must', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z7SSM5E9K7E09T1GK0MR2M', '01M0Z7SB2BKX98TG7HEH9T8ZGE', 'The expected value must not be recomputed by calling `identifierOf` in the check. An assertion comparing the wrapper''s answer against the function the wrapper calls has two outcomes that produce the same observed value, and it passes forever.', 'must_not', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z7SV095WXTEJX45MJA9XXS', '01M0Z7SB2BKX98TG7HEH9T8ZGE', 'A `numbering = ''none''` document, and a child-numbered document with no root-numbered ancestor, each come back with `reference` set to null and the call returns normally.', 'must', 5, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z7SWCAWAJYA9TG584CWWEA', '01M0Z7SB2BKX98TG7HEH9T8ZGE', 'A list containing one unnameable document among nameable ones must not lose rows or raise. Every row comes back, and only the unnameable one carries null.', 'must_not', 6, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z7SXRGWVVTRJZM683Y4151', '01M0Z7SB2BKX98TG7HEH9T8ZGE', 'The statement count for a fifty-row list is the same against a ten-document corpus and a two-hundred-document one.', 'must', 7, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z7SZ6SGCZFDHP3ZD74WBXA', '01M0Z7SBDBRPVRM6PV95EWMGMF', 'Every test asserting a returned document row by deep-equality against a literal is enumerated from the suite source, and the resulting list is empty. Such an assertion breaks on any additive field, which is what makes it the shape worth finding rather than a style preference.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z8C6387RG0YZ2QNPEXBDC2', '01M0Z8C15JD3B30GSKX46AQ8JJ', '`resolve_reference` given a reference matching exactly one document returns that document''s row.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z8C7FJ0GQHCFWM731Z7AXY', '01M0Z8C15JD3B30GSKX46AQ8JJ', 'A reference matching both an epic and its coverage matrix, called with `kind: ''epic''`, returns the epic.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z8C92RMYQYAQN213FCFVVZ', '01M0Z8C15JD3B30GSKX46AQ8JJ', 'Resolution issues a bounded number of statements against the database, and the count does not grow with the number of documents the project holds — measured against two corpora of different sizes.', 'must', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z8CAZ0H243TF9P2AXNH14R', '01M0Z8C15JD3B30GSKX46AQ8JJ', 'A reference read from any tool''s output is accepted verbatim by `resolve_reference` and returns the document it came from — a round trip over every document in the fixture corpus, with no transformation applied in between.', 'must', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z8CC9P0MK7KBYSXS99B0A9', '01M0Z8C1K74RSJ42VJRFS7BRPJ', 'A reference matching no document is refused, and the refusal message contains the reference that was looked for.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z8CDNTDDS2KD2H9R58F4E3', '01M0Z8C1K74RSJ42VJRFS7BRPJ', 'A reference matching both an epic and its coverage matrix, called with no `kind`, must not return either one. It is refused as ambiguous.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z8CFQZ9EPRATNDV3V3GBH7', '01M0Z8C1K74RSJ42VJRFS7BRPJ', 'The fixture holds a colliding pair — an epic and its coverage matrix — so the ambiguous path is reachable. Against a fixture with one epic and no matrix the ambiguity never fires and the two criteria above pass by never being exercised.', 'control', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z8CGEHV4VHMN4YMZ85S56Y', '01M0Z8C1K74RSJ42VJRFS7BRPJ', 'The refusal for an unresolvable reference names the references that do exist for that kind, so a mistyped one is corrected from the message.', 'must', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z8J9XT5H4ZPFNSKQKBMKN1', '01M0Z8J2QB4A27EFCCTZFSM3E5', '`dpm/shared/skill-conventions.md` carries a section governing what a skill says to a person, distinct from Cross-References, stating both the reference-and-title rule and what a skill does when the reference is null.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z8JB8YE0ESPFYMPTX5Z8EG', '01M0Z8J2QB4A27EFCCTZFSM3E5', 'The convention section states the stored-prose rule — a document named inside a body is written `{{ref:<id>}}` — as well as the rule for what a skill says to a person.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z8JCPYQJAVSPV75008TVHP', '01M0Z8J44R6FZ4EHW5QMJ8BCEA', 'No row of the status skill''s *Recommended next steps* table interpolates a document id into a command.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z8JER0FFH3X8TT17DAZFH9', '01M0Z8J44R6FZ4EHW5QMJ8BCEA', 'No skill file in the tree contains a placeholder interpolating a document id into a user-facing command or sentence. The corpus is enumerated by `everySkill()` reading the tree, never by a written list, so a skill added later is covered on the day it lands.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z8JGSJP1TE4ET80JSFPT7D', '01M0Z8J44R6FZ4EHW5QMJ8BCEA', 'The pattern the check uses, run against the status skill as it stands before this work, finds its four existing occurrences. A pattern that matches nothing passes against a corpus that still leaks, and nothing in the criterion above would say so.', 'control', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z8JJ75PSQJM3YAX0PN3KD5', '01M0Z8J4R96YPC326G0675X8GS', 'Each of the seven skills'' Input section states that a human reference is accepted alongside a ULID, and names `resolve_reference` — which the existing binding then holds to being a tool that exists.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z8JKKEYQDW29580Q9TPXN6', '01M0Z8J4R96YPC326G0675X8GS', 'The seven must not be swept from the tree. They are a fixed set this spec chose, so a skill added later is not silently in scope and its absence from the list is a decision rather than an oversight.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z8P2Y4QT4NG81CQ01JMHWT', '01M0Z8NVN0KF2ERJBWTHBJF7A3', 'A reference taken from a real document''s tool output, substituted into the command the status skill''s *Recommended next steps* table recommends, is accepted by the receiving skill''s Input contract and resolves back to that same document.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z92ZSX5ACPBHTN4WFN8XZ0', '01M0Z92TG3FBHV5XZF1Y9ENPE9', '`create_document_section` with a body containing a live document''s bare ULID is refused, and the message names the column and shows the `{{ref:<id>}}` form.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z931W2W7X6EERCJJF655NJ', '01M0Z92TG3FBHV5XZF1Y9ENPE9', 'The same ULID written correctly as `{{ref:<id>}}` in the same body must not be refused. A check that cannot tell the marker from the bare id refuses the only correct way to write the reference.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z933Y6NM6TK8TRVC7PGZ4A', '01M0Z92TG3FBHV5XZF1Y9ENPE9', 'Every prose-bearing write tool is covered, with the prose columns enumerated from the classification in `dpm/tests/support/prose-columns.js` rather than from a list of tool names — so a prose column added by a later migration is covered without an edit here.', 'must', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z935AASRTPYNBGBVKQD4PR', '01M0Z92TG3FBHV5XZF1Y9ENPE9', 'A foreign-key column accepts a live document''s ULID: `create_dependency` with `source_document_id` set to one is not refused.', 'must', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z936PTZB8ADQS489Y810F8', '01M0Z92TG3FBHV5XZF1Y9ENPE9', '`update_session` with a `state` blob containing a live document''s ULID is not refused. The blob is skill-defined, dpm does not interpret it, and nothing renders it.', 'must', 5, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z938S0XN5V33GEJVK5QXRY', '01M0Z92TG3FBHV5XZF1Y9ENPE9', 'A body containing a well-formed ULID that names no document — a session id quoted in an observation — is accepted. It has no marker form, so refusing it would reject prose with no correct alternative.', 'must', 6, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z93AW1190ZKJA1M1VDEMGT', '01M0Z92TG3FBHV5XZF1Y9ENPE9', 'A check without these exemptions refuses the foreign-key case — a sweep of every TEXT column against this project''s own database flagged 390 of them. The three criteria above are what stop the refusal rejecting correct content, and without the control they read as defensive padding rather than as the finding they are.', 'control', 7, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z93BJ49D5F1YWVTTBDCD4P', '01M0Z92VBH6BTBEWJC9138RJ8V', 'Publishing a fixture corpus produces no file under `docs/` containing a ULID that names a live document.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z9A5N3039FP4JA62SEEWM1', '01M0Z9A2R6V83YQF0T1M6GPE1S', 'The running Node satisfies `REQUIRED_NODE` in `dpm/src/server/node-floor.js`, and `engines.node` in `dpm/package.json` equals it.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z9A7Q841Q2219K5PDBKSNW', '01M0Z9A2R6V83YQF0T1M6GPE1S', '`npm test` from `dpm/` invokes `node --test` and resolves no test-runner binary from `node_modules`.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z9A93BPF2M8WBG0PY1KVYM', '01M0Z9A2R6V83YQF0T1M6GPE1S', '`dpm/src` and `dpm/skills` are present in the working tree, and `.git/hooks/pre-commit` resolves to `dpm/hooks/pre-commit` in that same tree rather than to a path under the plugin cache.', 'must', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z9AAGRADS836J79GNCK400', '01M0Z9A2R6V83YQF0T1M6GPE1S', 'Every test builds its planning data from `dpm/tests/support/planning-database.js`, and no test opens this project''s `.dpm/dpm.db`.', 'must', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z9ABVKP3TR7QBRXS2EV5ZA', '01M0Z9A2R6V83YQF0T1M6GPE1S', 'The suite can create a writable scratch directory, publish a fixture corpus into it, and read the rendered files back.', 'must', 5, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z9AD7PYEWNY7W1FPRP4PBJ', '01M0Z9A2R6V83YQF0T1M6GPE1S', '`dpm/package.json` declares empty `dependencies` and empty `devDependencies` after this work.', 'must', 6, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z9AEMQJD4D1342SJHFZSC5', '01M0Z9A2R6V83YQF0T1M6GPE1S', 'The suite runs to completion with no `node_modules` directory present.', 'must', 7, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z9AFZZGAW899TV0EEW23GR', '01M0Z9A2R6V83YQF0T1M6GPE1S', 'The whole suite runs to completion from a local `npm test`, and the repository has no `.github/workflows` directory.', 'must', 8, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z9AHC22ZNME32NMGB9H3PK', '01M0Z9A2R6V83YQF0T1M6GPE1S', 'The suite runs to completion with the plugin cache directory absent or read-only.', 'must', 9, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z9AJR6A9TE0K4MTT6T8MZY', '01M0Z9A2R6V83YQF0T1M6GPE1S', 'The suite runs against a database at the schema version the installed release targets, and no tool this work adds requires a column that version lacks.', 'must', 10, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M0Z9AKFPEX4BD4CESKWSYE86', '01M0Z9A2R6V83YQF0T1M6GPE1S', 'Every tool this work adds answers correctly against a database whose `docs/` tree has never been published.', 'must', 11, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11YXJFG5AEZ9243ATY9R3PX', '01M11YXDHMJXHDV0EED6H83MHW', 'The retirement columns on coverage carry the same paired CHECK that artifact and observation carry, read from the live schema rather than transcribed into the test.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11YXKVKH7C64QKHDRKY32NW', '01M11YXDHMJXHDV0EED6H83MHW', 'The supersession column on story_criterion yields an include_superseded flag and the retirement column on coverage yields an include_retired flag, both derived from the column name rather than declared.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11YXN7SK7XYEXB0DGD8VWYP', '01M11YXDHMJXHDV0EED6H83MHW', 'No column this change adds introduces a third spelling of retirement or of supersession.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11YXPKS3TBZVTP5NXTQ12TF', '01M11YXDHMJXHDV0EED6H83MHW', 'The migration file states what the claim hash now excludes, and states that no existing claim is invalidated by it because no row is retired at migration time.', 'must', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11YXQZVP6S6N1CR07N0872J', '01M11YXEXXJP5C2VZ14A7J8V50', 'A database at the previous schema version, holding coverage rows and story criteria, migrates with every one of them live: retired_at and superseded_at are null throughout.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11YXSC5N8R8K3JPY2QB8PKM', '01M11YXEXXJP5C2VZ14A7J8V50', 'The claim hash over a requirement with no retired bindings returns the same digest before and after the migration, so every standing claim survives it.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11YXTR4R2AJMZYZ18QAZT8A', '01M11YXEXXJP5C2VZ14A7J8V50', 'Migrating must not drop a coverage_story row, an index or a trigger.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11YXW4GCC02HAFA7CNPEQSA', '01M11YXEXXJP5C2VZ14A7J8V50', 'A migrated schema and a freshly created one must not differ, object for object.', 'must_not', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11YXXGE6D1QMQD52ES28GTZ', '01M11YXEXXJP5C2VZ14A7J8V50', 'A coverage_story row present before the rebuild is present after it, carrying the same pair, so the rescue put back what it took aside.', 'control', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11YXYWFY859RJ3ASREEV1VQ', '01M11YXFAMERGVJCANDSTSKK1S', 'The suite runs to completion on Node 22.5.0 or later using node --test, with DatabaseSync imported from node:sqlite.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11YY08KTAQYCB935SD7N90R', '01M11YXFAMERGVJCANDSTSKK1S', 'A test creates a database at the previous schema version and migrates it in-process, without opening the project''s own planning database.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11YY1MQNG1S6GSWFK960TP2', '01M11YXFAMERGVJCANDSTSKK1S', 'A project database at the previous schema version reaches the new one on first start, in a single transaction, with no SQLite beyond the one built into Node.', 'must', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11YY313046BGYD1BZCXN5S8', '01M11YXFAMERGVJCANDSTSKK1S', 'The suite runs with no dependencies and no devDependencies installed, and the manifest declares none.', 'must_not', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11YY4D0JD6T1PH6N78698H4', '01M11YXFAMERGVJCANDSTSKK1S', 'No test in the suite opens the project''s own planning database for writing.', 'must_not', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11YY56R98WVK8JD637HHZF1', '01M11YXFAMERGVJCANDSTSKK1S', 'Migrating must not require a project to run a command, edit a file or repair a row by hand.', 'must_not', 5, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11Z4W0WN253Z98B5TG5FF8B', '01M11Z4NW96EHYMFQYF8147WSH', 'retire_coverage sets retired_at and retired_reason together on a live binding, and read_coverage on that id returns both.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11Z4XD035V5VGJ69FZASFQF', '01M11Z4NW96EHYMFQYF8147WSH', 'list_coverage omits a retired binding by default and returns it when include_retired is passed.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11Z4YS6YKKH0JXPJWRBHD4H', '01M11Z4NW96EHYMFQYF8147WSH', 'update_coverage does not set retired_at or retired_reason. Retirement is its own tool, as it is for every other retirable thing in the surface.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11Z505B0PG3M0R09XP9RGNM', '01M11Z4NW96EHYMFQYF8147WSH', 'No tool in the registered surface deletes a coverage row.', 'must_not', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11Z51HDNT4V7B04KK2ES3TX', '01M11Z4NW96EHYMFQYF8147WSH', 'update_coverage still sets position and verified_at on the same row, so the refusal above is specific to the retirement columns rather than a tool that updates nothing.', 'control', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11Z52XHHB7ZR6N9XRH8TF8N', '01M11Z4Q9BW7NAQT8SV0CT4751', 'retire_coverage called with no reason is refused, and the row is unchanged afterwards.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11Z549X6KT221M42H3AP2BC', '01M11Z4Q9BW7NAQT8SV0CT4751', 'That refusal is a boundary rejection naming the missing argument, rather than an internal error surfacing from the schema.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11Z55NRECN8GVWY7Y6J800W', '01M11Z4Q9BW7NAQT8SV0CT4751', 'A row must not exist with retired_at set and retired_reason null, whatever writes it. The tool is one path to that state and a direct write is another.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11Z571X76039DJ1WA6RY3QS', '01M11Z4Q9BW7NAQT8SV0CT4751', 'retire_coverage with a reason succeeds on the same binding, so the refusals above are the missing reason rather than a tool that refuses everything.', 'control', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11Z58E7CC905RMH34SJXPP7', '01M11Z4QYY9NX52N7HHCB9C8HC', 'Retiring one of three bindings on a claimed requirement clears coverage_claimed_at and coverage_claim_hash together.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11Z59T4H2YCEFGS8RPXRBMM', '01M11Z4QYY9NX52N7HHCB9C8HC', 'A claim made after the retirement hashes over the remaining bindings only, and claimState reports that claim current.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11Z5B7HJRMQ09BBR5W1EQ2G', '01M11Z4QYY9NX52N7HHCB9C8HC', 'A retired binding does not count toward the bound total claimState reports.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11Z5BWBY8BGBP70EFJKN3JX', '01M11Z4QYY9NX52N7HHCB9C8HC', 'No project is required to re-make a claim it had already made, as a consequence of this change.', 'must_not', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11Z5D96CKSH8MJ5T3CQ5QYF', '01M11Z4QYY9NX52N7HHCB9C8HC', 'Retiring one binding does not clear verified_at on any other live binding of the same requirement.', 'must_not', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11Z5FAMBMNHYW6P4ZATCDHR', '01M11Z4QYY9NX52N7HHCB9C8HC', 'Retiring a binding on one requirement leaves another requirement''s standing claim intact, so the withdrawal is scoped rather than a trigger that unclaims everything.', 'control', 5, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11Z5GPSKX50AJB5QWW2NXZF', '01M11Z4QYY9NX52N7HHCB9C8HC', 'A live binding on the same requirement still counts toward the bound total, so the exclusion above is the retirement rather than a count that returns zero.', 'control', 6, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11Z5J2VPRQ3Q49D5H7G6JPC', '01M11Z4QYY9NX52N7HHCB9C8HC', 'A requirement with a retired binding is unclaimed, so claims surviving a migration is the migration leaving them alone rather than claims never being cleared at all.', 'control', 7, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11Z5KEZKT8Y25NBQ6TEN8H6', '01M11Z4RXQMCNQ57EGQMJC7ETH', 'After retiring a binding, create_coverage with the same requirement, fragment and criterion succeeds and yields a live row.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11Z5MV33XQD4KAKVTWBFW06', '01M11Z4RXQMCNQ57EGQMJC7ETH', 'The retired row and its live replacement coexist, and only the live one counts toward the bound total.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11Z5P76NGTP1E4BPRPWCWQC', '01M11Z4RXQMCNQ57EGQMJC7ETH', 'Two live bindings on the same triple must not exist: creating a second while the first is live is still refused.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11Z5QKBH1MVNPZ9FQTV70X5', '01M11Z4RXQMCNQ57EGQMJC7ETH', 'Recovering from a mistaken retirement must not require destroying the requirement or the criterion the binding hangs between.', 'must_not', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11Z5R9FVZHWVHKSWFGFVPTB', '01M11Z4RXQMCNQ57EGQMJC7ETH', 'Two retired bindings on the same triple can exist — retire, re-create, retire again — so the index constrains live rows rather than the table.', 'control', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11ZFT2NYN4YSY5FEYMRX27B', '01M11ZFN61V69YPHKWDBGC4KPC', 'update_story_criterion sets superseded_at and superseded_reason together, and the criterion''s own text is unchanged by that call.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11ZFVESWAZJAVHJBB670F8G', '01M11ZFN61V69YPHKWDBGC4KPC', 'list_story_criterion omits a superseded criterion by default and returns it when include_superseded is passed.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11ZFWTV891FPAX4TH57D897', '01M11ZFN61V69YPHKWDBGC4KPC', 'A row must not exist with superseded_at set and superseded_reason null.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11ZFY6YEJC19TBBG8KNTDBQ', '01M11ZFN61V69YPHKWDBGC4KPC', 'Superseding a criterion must not clear the verification of bindings on other criteria of the same story.', 'must_not', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11ZFZK1Y0VXZ868HQF1W12Z', '01M11ZFN61V69YPHKWDBGC4KPC', 'The same call passing the criterion''s text back byte-identical leaves its bindings'' verification standing, so a cleared mark is the supersession rather than a trigger firing on any write.', 'control', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11ZG0Z5NMJVJCDGPM3W4C1E', '01M11ZFNW90GZNGWFCKSP20PGS', 'Superseding a criterion retires every binding hanging off it, each carrying a reason that names the supersession.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11ZG2B8PN0J806H7WRECJR0', '01M11ZFNW90GZNGWFCKSP20PGS', 'Those bindings are still readable under include_retired, with their spec_fragment intact.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11ZG3QDB9DPHC7WZ3X9P3XA', '01M11ZFNW90GZNGWFCKSP20PGS', 'A superseded criterion''s bindings must not remain in the set a completeness claim hashes over, so a requirement claimed before the supersession is unclaimed by it.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11ZG53JM67E181V170QZBHE', '01M11ZFNW90GZNGWFCKSP20PGS', 'Bindings on a live criterion of the same story are untouched, so the retirement follows the criterion rather than the story.', 'control', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11ZG6FM2BN7PZMPYRATN58A', '01M11ZFNW90GZNGWFCKSP20PGS', 'The supersession-driven retirement satisfies the paired-reason constraint, which is the one retirement path where no caller supplies the reason.', 'control', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11ZG7VRB8EWVGV4KH6E5KMZ', '01M11ZFPT4MVB8GMA161EE4GTV', 'update_story_criterion sets warrant_adr_id, and refuses an id that does not name an accepted decision.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11ZG97XFJY3Y1VHDQ1K1JJZ', '01M11ZFPT4MVB8GMA161EE4GTV', 'The roll-up reads a criterion carrying a warrant and no binding as accounted for, and one carrying neither as unbound.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11ZGAM03VY9YZN1EFAXY5CH', '01M11ZFPT4MVB8GMA161EE4GTV', 'A criterion carrying a warrant must not be reported as an unbound gap.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11ZGC058765GJD48GR6F1V0', '01M11ZFPT4MVB8GMA161EE4GTV', 'A criterion carrying neither a warrant nor a live binding is reported as an unbound gap, so the exemption above is the warrant rather than the report going quiet.', 'control', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11ZGCZH9JKM3HDQEPEEBMH2', '01M11ZFPT4MVB8GMA161EE4GTV', 'A criterion carrying both a warrant and a live binding still counts its binding, so a warrant does not substitute for a binding where requirement text exists to quote.', 'control', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11ZNW6KYZS5TYWPQ41A1D2P', '01M11ZNRM6XZZ1Y9MXYEYW9Q3C', 'A binding whose fragment its requirement no longer contains is named by integrity entry 9 while that binding is live.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11ZNXJQN1VGRSKP0SJEZ94K', '01M11ZNRM6XZZ1Y9MXYEYW9Q3C', 'Retiring that same binding removes it from entry 9, which then reports held true, with nothing else in the database changed.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11ZNYYH1SN2T8EEPDQCRFZC', '01M11ZNRM6XZZ1Y9MXYEYW9Q3C', 'Entry 9 does not name a retired binding whose fragment is still a substring of its requirement.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11ZP0CPFFCKWZQ5NCVVVW72', '01M11ZNRM6XZZ1Y9MXYEYW9Q3C', 'A second live binding, broken in the same requirement, is still named after the first is retired, so entry 9 going quiet is the retirement rather than the entry ceasing to look.', 'control', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11ZP1Q20DQTBSACPB7BZR5A', '01M11ZNRY055EM70JPZNRV9Z5Q', 'A binding retired while its fragment was still a substring of its requirement, and while its criterion was still live, is named by an integrity entry of its own, which is advisory: reported, and never blocking a restore.', 'must', 0, NULL, NULL, '01M11RZ786GQV5EWA0NTJPEHSE');
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11ZP6KHEGE6TZNXVPG4M42K', '01M11ZNRY055EM70JPZNRV9Z5Q', 'That entry and entry 9 are separate: a broken live binding is named by entry 9 and not by the new one.', 'must', 1, NULL, NULL, '01M11RZ786GQV5EWA0NTJPEHSE');
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11ZP6V45E2NNNCPC2R56CNP', '01M11ZNRY055EM70JPZNRV9Z5Q', 'The new entry does not name a binding retired while its fragment no longer matched its requirement.', 'must_not', 2, NULL, NULL, '01M11RZ786GQV5EWA0NTJPEHSE');
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M11ZP7F5BA7HF3H7SS6S24XN', '01M11ZNRY055EM70JPZNRV9Z5Q', 'Retiring a sound binding still succeeds, so the new entry reports the retirement rather than refusing it.', 'control', 3, NULL, NULL, '01M11RZ786GQV5EWA0NTJPEHSE');
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1209E9B7WVG5D9J1CYN74C7', '01M12099CA9KWDG7DSBDCS1J7N', 'A pivot run amending a requirement''s text names every binding whose fragment the amended text no longer contains, and names no others.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1209FHRBGBX4DHNHZ1M2MG7', '01M12099CA9KWDG7DSBDCS1J7N', 'Each named binding is offered under its own approval: a run that approves one of two retires that one.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1209GXXQ2WSZPV2H8JP2HVW', '01M12099CA9KWDG7DSBDCS1J7N', 'The pivot does not retire a binding the run did not approve.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1209JBYA0N09YZ0W8QFWWPG', '01M12099CA9KWDG7DSBDCS1J7N', 'The pivot does not recover the bindings by reading a generated markdown file instead of calling the list tool.', 'must_not', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1209KP6XP133BRQ7AH42Z81', '01M12099CA9KWDG7DSBDCS1J7N', 'A run amending a requirement whose bound fragments all survive names no binding and offers no retirement, so naming nothing is the amendment rather than a step that never ran.', 'control', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1209N29VBG266KFWRCPCPW8', '01M1209ARJTGAVYY2NCT5JS3PJ', 'The breakdown skill''s coverage step instructs that a fragment be quoted from the clause carrying the obligation, and says why connective phrasing is the fragment an amendment breaks.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1209PEJ9RCBM38MK1BXYZXY', '01M1209ARJTGAVYY2NCT5JS3PJ', 'A breakdown run over a requirement whose obligation and connective wording are separable binds the obligation clause.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1209QTJSA343PBJJBG60FKC', '01M1209ARJTGAVYY2NCT5JS3PJ', 'That instruction must not weaken the existing refusal of a fragment traceable to no spec text.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1209S6Q9CMGS6305RZZAFQQ', '01M1209B39K3D8E6833NWHEKJ5', 'The execution roll-up''s sentence names the remaining bindings rather than implying every binding ever made was verified.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M1209SRT606A01YRHY1YYXVS', '01M1209B39K3D8E6833NWHEKJ5', 'The roll-up must not report a count that includes retired bindings.', 'must_not', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M120MG2YZKTC4Q9JZE5TPS8J', '01M120MC8VEJTG7WYFRN3WPCK2', 'Every TEXT column this change adds carries a prose-columns classification, reconciled in both directions so a column added later fails until judged and an entry for a column the schema no longer has fails too.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M120MHFD7DJ12WPYXCT9PFYW', '01M120MC8VEJTG7WYFRN3WPCK2', 'The retirement tool is registered and reached by the parity sweeps without an exemption.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M120MJY84E4DSK8H71KVD08R', '01M120MC8VEJTG7WYFRN3WPCK2', 'No column or tool this change adds is exempted from a derived sweep.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M120MKPQ0945X2GF3J9NAFCP', '01M120MCTWM0FSCTQZRCF22HM8', 'After the schema version bumps, reinstalling the plugin from this working tree restores write access to this project''s database, which the integrity report describes as skew until it happens.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M122V3T36JVCX702WFBF6QX6', '01M122TPQ7F6ZJ2CA8438NJ513', 'retire_coverage sets retired_at and retired_reason together on a live binding, and read_coverage on that id returns both.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M122V56EA9SH0YJZHV95WKNH', '01M122TPQ7F6ZJ2CA8438NJ513', 'list_coverage omits a retired binding by default and returns it when include_retired is passed.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M122V6JJPHG2WMT37PVNXR8H', '01M122TPQ7F6ZJ2CA8438NJ513', 'update_coverage does not set retired_at or retired_reason. Retirement is its own tool, as it is for every other retirable thing in the surface.', 'must_not', 2, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M122V7Z9DW1DQM3KDT0MEV1W', '01M122TPQ7F6ZJ2CA8438NJ513', 'No tool in the registered surface deletes a coverage row.', 'must_not', 3, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M122VA0S5G1S8HQ1PZ87YMJ3', '01M122TPQ7F6ZJ2CA8438NJ513', 'update_coverage still sets position and verified_at on the same row, so the refusal above is specific to the retirement columns rather than a tool that updates nothing.', 'control', 4, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M122VBCRFTTX5SMEDG5X5WVS', '01M122TQ5WBTX9XAH9ATSV9X49', 'update_story_criterion sets superseded_at and superseded_reason together, and the criterion''s own text is unchanged by that call.', 'must', 0, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M122VCS10ZXXCDDVPX3GQG94', '01M122TQ5WBTX9XAH9ATSV9X49', 'list_story_criterion omits a superseded criterion by default and returns it when include_superseded is passed.', 'must', 1, NULL, NULL, NULL);
INSERT INTO "story_criterion" ("id", "story_id", "text", "polarity", "position", "superseded_at", "superseded_reason", "warrant_adr_id") VALUES ('01M122VDFG1SHN0VCNZ2TX9G4W', '01M122TQ5WBTX9XAH9ATSV9X49', 'A row must not exist with superseded_at set and superseded_reason null.', 'must_not', 2, NULL, NULL, NULL);
