INSERT INTO "document" ("id", "kind", "numbering", "number", "sequence", "slug", "title", "status", "status_note", "parent_id", "parent_kind", "archived_at", "commit_sha", "created_at", "updated_at", "retro_waived_at", "retro_waived_reason") VALUES ('01M11RWKX5T02H6R1P06EQX8XH', 'adr', 'child', NULL, 4, 'marking-an-overtaken-criterion', 'How an overtaken story criterion is marked, and what becomes of its bindings', 'pending', 'Accepted with the duplicated fact understood rather than discovered: a superseded criterion''s state is copied onto its bindings, and the two can be made to disagree by a direct write. The copy is repairable because re-binding is an ordinary create, which is what decided it against the join condition.', '01M11F97T7W9ZJVCTC1E1DQGJG', 'spec', NULL, NULL, '2026-08-27T14:09:55.109Z', '2026-08-27T14:10:24.168Z', NULL, NULL);
